-- Import via phpMyAdmin (pilih database laksanatech → Import)
-- Aman dijalankan berulang: pakai INSERT ... ON DUPLICATE KEY UPDATE

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1) Tambah kolom live_demo_url
-- Jalankan baris di bawah SEKALI. Jika error "Duplicate column name", lewati.
ALTER TABLE `templates` ADD COLUMN `live_demo_url` VARCHAR(255) NULL AFTER `demo_url`;

-- 2) Kategori template

UPDATE `template_categories` SET `is_active` = 0 WHERE `slug` = 'website';

-- 3) Template aktif (live demo URL)

